def last_stone_weight(stones):
 import heapq
 heap=[-x for x in stones];heapq.heapify(heap)
 while len(heap)>1:
  first=-heapq.heappop(heap);second=-heapq.heappop(heap)
  if first!=second:heapq.heappush(heap,second-first)
 return -heap[0] if heap else 0

